      <select id="car-fragrance" v-model="selectedId">
        <option value="" disabled>Select your scent</option>
        <option v-for="item in items" :key="item.id" :value="item.id">
          {{ item.name }} — {{ formatPrice(item.basePrice) }}
        </option>
      </select>

      <div v-if="selected" class="selection">
        <span>{{ selected.notes }}</span>
        <strong>{{ formatPrice(selected.basePrice) }}</strong>
      </div>
      <button type="button" :disabled="!selected" @click="addToCart">
        Add car aroma to bag
      </button>
    </div>
  </section>
</template>

<script>
import { formatPrice } from '../data/products'

export default {
  name: 'CarAromas',
  props: {
    items: { type: Array, required: true }
  },
  data: () => ({ selectedId: '' }),
  computed: {
    selected() {
      return this.items.find(item => item.id === this.selectedId)
    }
  },
  methods: {
    formatPrice,
    addToCart() {
      this.$emit('add-to-cart', {
        cartKey: this.selected.id,
        productId: this.selected.id,
        name: `${this.selected.name} Car Aroma`,
        variantLabel: 'Car diffuser',
        price: this.selected.basePrice
      })
      this.selectedId = ''
    }
  }
}
</script>

